def build_live_thesis_detail_response(
    parsed: ParsedApiPath,
    *,
    config: RuntimeConfig,
    executor: PsqlCommandExecutor | None,
    generated_at: str,
) -> dict[str, Any]:
    identifier = _parse_detail_identifier(parsed.path, "/api/theses/")
    state = load_frontend_thesis_detail_state(config=config, executor=executor, identifier=identifier)
    symbol = str(state.get("symbol") or "UNKNOWN").upper()
    latest_review = _as_dict(state.get("latest_review"))
    evidence = [_build_thesis_evidence_payload(item) for item in _as_list(state.get("evidence"))]
    core_claims = [str(item) for item in state.get("core_claims", [])] if isinstance(state.get("core_claims"), list) else []
    invalidation_conditions = [
        _build_invalidation_condition_payload(item)
        for item in _as_list(state.get("invalidation_conditions"))
    ]
    equity_research = _build_stock_equity_research_payload(_as_dict(state.get("equity_research")))
    valuation_target_range = _build_valuation_target_range_payload(
        _as_list(state.get("valuation_methods")),
        symbol=symbol,
        as_of_date=str(state.get("as_of_date") or ""),
        currency_code=str(state.get("currency_code") or "USD"),
    )
    lifecycle = _build_thesis_lifecycle_payload(
        state=state,
        symbol=symbol,
        core_claims=core_claims,
        invalidation_conditions=invalidation_conditions,
        latest_review=latest_review,
        equity_research=equity_research,
        valuation_target_range=valuation_target_range,
    )
    evidence_review = _build_thesis_evidence_review_payload(
        evidence=evidence,
        invalidation_conditions=_as_list(state.get("invalidation_conditions")),
        latest_review=latest_review,
    )
    professional_lifecycle_gates = _build_thesis_professional_lifecycle_gates_payload(
        lifecycle=lifecycle,
        evidence=evidence,
        evidence_review=evidence_review,
        latest_review=latest_review,
        valuation_target_range=valuation_target_range,
        generated_at=generated_at,
    )

    return {
        "contract_version": CONTRACT_VERSION,
        "generated_at": generated_at,
        "data": {
            "thesis_id": _thesis_detail_id(state, identifier),
            "symbol": symbol,
            "instrument_id": _opaque_id("instrument", state.get("instrument_id"), symbol.lower()),
            "currency_code": str(state.get("currency_code") or "USD"),
            "status": str(state.get("status") or "unknown"),
            "thesis_version": str(state.get("thesis_version") or "bootstrap-v1"),
            "created_from_recommendation_id": _opaque_id(
                "recommendation",
                state.get("created_from_recommendation_id"),
                None,
            )
            if state.get("created_from_recommendation_id") is not None
            else None,
            "summary": str(state.get("summary") or ""),
            "core_claims": core_claims,
            "invalidation_conditions": invalidation_conditions,
            "latest_review": {
                "review_id": _opaque_id("thesis-review", latest_review.get("review_id"), None)
                if latest_review.get("review_id") is not None
                else None,
                "action": str(latest_review.get("action") or "unreviewed"),
                "risk_level": str(latest_review.get("risk_level") or "unknown"),
                "reviewed_at": _timestamp(latest_review.get("reviewed_at")),
                "summary": str(latest_review.get("summary") or ""),
                "change_notes": str(latest_review.get("change_notes") or ""),
                "next_review_date": _timestamp(latest_review.get("next_review_date")),
            },
            "lifecycle": lifecycle,
            "professional_lifecycle_gates": professional_lifecycle_gates,
            "valuation_target_range": valuation_target_range,
            "evidence": evidence,
            "evidence_review": evidence_review,
        },
        "links": _thesis_detail_links(state, identifier=identifier),
    }


def _build_thesis_lifecycle_payload(
    *,
    state: dict[str, Any],
    symbol: str,
    core_claims: list[str],
    invalidation_conditions: list[dict[str, str]],
    latest_review: dict[str, Any],
    equity_research: dict[str, Any] | None,
    valuation_target_range: dict[str, Any] | None,
) -> dict[str, Any]:
    research = equity_research or {}
    catalysts = _dedupe_lifecycle_items(
        [*(_as_scalar_list(research.get("catalysts"))), *_split_lifecycle_text(state.get("entry_conditions"))]
    )
    risks = _dedupe_lifecycle_items(_as_scalar_list(research.get("risks")))
    merged_invalidations = _merge_lifecycle_invalidation_conditions(
        existing=invalidation_conditions,
        research_conditions=_as_scalar_list(research.get("invalidation_conditions")),
        exit_conditions=_split_lifecycle_text(state.get("exit_conditions")),
    )
    valuation = _build_thesis_lifecycle_valuation(_as_dict(research.get("valuation_sensitivity")))
    if not valuation.get("has_view") and _as_dict(valuation_target_range).get("status") == "available":
        valuation = {
            **valuation,
            "base_case": _valuation_target_range_case_text(_as_dict(valuation_target_range)),
            "margin_of_safety_view": _format_signed_percent_text(
                _number(_as_dict(valuation_target_range).get("margin_of_safety"))
            ),
            "confidence": _number(_as_dict(valuation_target_range).get("confidence")),
            "has_view": True,
        }
    missing_items = _thesis_lifecycle_missing_items(
        core_claims=core_claims,
        catalysts=catalysts,
        risks=risks,
        invalidation_conditions=merged_invalidations,
        valuation=valuation,
        latest_review=latest_review,
    )
    if not core_claims or not merged_invalidations:
        readiness_status = "blocked"
    elif missing_items:
        readiness_status = "needs_detail"
    else:
        readiness_status = "complete"

    summary = str(research.get("korean_summary") or state.get("summary") or "")
    return {
        "source": "equity_research_artifact" if research.get("artifact_id") else "thesis_record",
        "equity_research_artifact_id": research.get("artifact_id"),
        "buy_case": {
            "symbol": symbol,
            "summary": summary,
            "core_claims": core_claims,
        },
        "catalysts": catalysts,
        "risks": risks,
        "invalidation_conditions": merged_invalidations,
        "valuation": valuation,
        "review_cadence": {
            "latest_review_action": str(latest_review.get("action") or "unreviewed"),
            "risk_level": str(latest_review.get("risk_level") or "unknown"),
            "reviewed_at": _timestamp(latest_review.get("reviewed_at")),
            "next_review_date": _timestamp(latest_review.get("next_review_date")),
            "summary": str(latest_review.get("summary") or ""),
        },
        "readiness": {
            "status": readiness_status,
            "missing_items": missing_items,
            "core_claim_count": len(core_claims),
            "catalyst_count": len(catalysts),
            "risk_count": len(risks),
            "invalidation_count": len(merged_invalidations),
            "has_valuation_view": bool(valuation.get("has_view")),
            "has_next_review_date": bool(_timestamp(latest_review.get("next_review_date"))),
        },
    }


def _dedupe_lifecycle_items(values: list[object]) -> list[str]:
    items: list[str] = []
    seen: set[str] = set()
    for value in values:
        item = str(value or "").strip()
        if not item:
            continue
        key = item.lower()
        if key in seen:
            continue
        seen.add(key)
        items.append(item)
    return items


def _split_lifecycle_text(value: object) -> list[str]:
    if value is None:
        return []
    if isinstance(value, list):
        return _dedupe_lifecycle_items(value)
    text = str(value).strip()
    if not text:
        return []
    return _dedupe_lifecycle_items(
        part.strip(" -\t")
        for part in re.split(r"(?:\r?\n|;|ㆍ|•|\|)", text)
    )


def _merge_lifecycle_invalidation_conditions(
    *,
    existing: list[dict[str, str]],
    research_conditions: list[object],
    exit_conditions: list[str],
) -> list[dict[str, str]]:
    merged: list[dict[str, str]] = []
    seen: set[str] = set()

    def add(condition: object, status: object = "not_triggered") -> None:
        condition_text = str(condition or "").strip()
        if not condition_text or condition_text == "not_defined":
            return
        key = condition_text.lower()
        if key in seen:
            return
        seen.add(key)
        merged.append(
            {
                "condition": condition_text,
                "current_status": str(status or "not_triggered"),
            }
        )

    for item in existing:
        add(item.get("condition"), item.get("current_status"))
    for item in research_conditions:
        add(item)
    for item in exit_conditions:
        add(item)
    return merged


def _build_thesis_lifecycle_valuation(valuation: dict[str, Any]) -> dict[str, Any]:
    base_case = _optional_text(valuation.get("base_case"))
    upside_case = _optional_text(valuation.get("upside_case"))
    downside_case = _optional_text(valuation.get("downside_case"))
    margin_of_safety_view = _optional_text(
        valuation.get("margin_of_safety_view")
        or valuation.get("margin_of_safety")
        or valuation.get("mos_view")
    )
    raw = {str(key): value for key, value in valuation.items()}
    has_view = any(
        value
        for value in (
            base_case,
            upside_case,
            downside_case,
            margin_of_safety_view,
        )
    ) or bool(raw)
    return {
        "base_case": base_case,
        "upside_case": upside_case,
        "downside_case": downside_case,
        "margin_of_safety_view": margin_of_safety_view,
        "confidence": _number(valuation.get("confidence")) if valuation.get("confidence") is not None else None,
        "raw": raw,
        "has_view": has_view,
    }


def _thesis_lifecycle_missing_items(
    *,
    core_claims: list[str],
    catalysts: list[str],
    risks: list[str],
    invalidation_conditions: list[dict[str, str]],
    valuation: dict[str, Any],
    latest_review: dict[str, Any],
) -> list[str]:
    missing: list[str] = []
    if not core_claims:
        missing.append("core_claims")
    if not catalysts:
        missing.append("catalysts")
    if not risks:
        missing.append("risks")
    if not invalidation_conditions:
        missing.append("invalidation_conditions")
    if not valuation.get("has_view"):
        missing.append("valuation_sensitivity")
    if not _timestamp(latest_review.get("next_review_date")):
        missing.append("next_review_date")
    return missing


def _build_thesis_professional_lifecycle_gates_payload(
    *,
    lifecycle: dict[str, Any],
    evidence: list[dict[str, Any]],
    evidence_review: dict[str, Any],
    latest_review: dict[str, Any],
    valuation_target_range: dict[str, Any] | None,
    generated_at: str,
) -> dict[str, Any]:
    readiness = _as_dict(lifecycle.get("readiness"))
    review_cadence = _as_dict(lifecycle.get("review_cadence"))
    valuation = _as_dict(lifecycle.get("valuation"))
    target_range = _as_dict(valuation_target_range)
    target_range_available = target_range.get("status") == "available"
    invalidations = _as_list(lifecycle.get("invalidation_conditions"))
    evidence_summary = _as_dict(evidence_review.get("summary"))

    core_claim_count = _integer(readiness.get("core_claim_count")) or 0
    catalyst_count = _integer(readiness.get("catalyst_count")) or 0
    risk_count = _integer(readiness.get("risk_count")) or 0
    invalidation_count = _integer(readiness.get("invalidation_count")) or 0
    triggered_invalidation_count = sum(
        1 for item in invalidations if str(item.get("current_status") or "unknown") != "not_triggered"
    )
    source_event_count = _integer(evidence_summary.get("source_event_count")) or 0
    performance_evidence_count = _integer(evidence_summary.get("performance_evidence_count")) or 0
    evidence_count = len(evidence)
    latest_reviewed_at = _timestamp(latest_review.get("reviewed_at") or review_cadence.get("reviewed_at"))
    next_review_date = _timestamp(latest_review.get("next_review_date") or review_cadence.get("next_review_date"))
    generated_dt = _parse_frontend_datetime(generated_at)
    next_review_dt = _parse_frontend_datetime(next_review_date)
    latest_review_dt = _parse_frontend_datetime(latest_reviewed_at)
    evidence_times = [
        parsed
        for parsed in (_parse_frontend_datetime(item.get("observed_at")) for item in evidence)
        if parsed is not None
    ]
    latest_evidence_dt = max(evidence_times) if evidence_times else None
    latest_evidence_at = _format_frontend_datetime(latest_evidence_dt)
    review_overdue = bool(next_review_dt and generated_dt and next_review_dt.date() < generated_dt.date())
    new_evidence_after_review = bool(
        latest_evidence_dt
        and latest_review_dt
        and latest_evidence_dt.replace(tzinfo=timezone.utc) > latest_review_dt.replace(tzinfo=timezone.utc)
    )

    gates = [
        _thesis_lifecycle_gate(
            gate_key="buy_case",
            title="왜 보유하는가",
            status="pass" if core_claim_count else "blocked",
            decision="핵심 주장이 있어야 장기 thesis로 취급한다",
            detail=(
                f"핵심 주장 {core_claim_count}개가 연결되어 있다."
                if core_claim_count
                else "핵심 주장이 없어 이 thesis를 장기 투자 판단 입력으로 쓰면 안 된다."
            ),
            next_step="핵심 주장과 사업/재무 근거를 보강한다." if not core_claim_count else "핵심 주장이 원천 근거와 계속 맞는지 본다.",
            facts=[
                _professional_fact("핵심 주장", f"{core_claim_count}개"),
                _professional_fact("생애주기 상태", _professional_code_label(readiness.get("status"))),
            ],
        ),
        _thesis_lifecycle_gate(
            gate_key="catalysts",
            title="무엇이 맞아야 하는가",
            status="pass" if catalyst_count else "warning",
            decision="성립 조건과 촉매가 있어야 기대 경로를 검토할 수 있다",
            detail=(
                f"성립 조건/촉매 {catalyst_count}개가 연결되어 있다."
                if catalyst_count
                else "성립 조건이나 촉매가 없어 무엇이 맞아야 하는지 불분명하다."
            ),
            next_step="매수 논리가 현실화되기 위한 촉매와 확인 지표를 보강한다." if not catalyst_count else "촉매가 실제 데이터로 진행되는지 추적한다.",
            facts=[_professional_fact("촉매", f"{catalyst_count}개")],
        ),
        _thesis_lifecycle_gate(
            gate_key="risks",
            title="무엇을 조심해야 하는가",
            status="pass" if risk_count else "warning",
            decision="반대 논리와 리스크가 있어야 과신을 줄일 수 있다",
            detail=(
                f"리스크 {risk_count}개가 연결되어 있다."
                if risk_count
                else "리스크가 분리되어 있지 않아 thesis가 한쪽 방향으로만 쓰일 위험이 있다."
            ),
            next_step="사업, 재무, 밸류에이션, 경쟁 리스크를 분리해 보강한다." if not risk_count else "리스크가 커지는 증거를 새 뉴스/실적과 대조한다.",
            facts=[_professional_fact("리스크", f"{risk_count}개")],
        ),
        _thesis_lifecycle_gate(
            gate_key="invalidation",
            title="무엇이 틀리면 나가는가",
            status="blocked" if triggered_invalidation_count or not invalidation_count else "pass",
            decision="무효화 조건은 반드시 있어야 한다",
            detail=(
                f"무효화 조건 {invalidation_count}개 중 {triggered_invalidation_count}개가 발동 상태다."
                if triggered_invalidation_count
                else (
                    f"무효화 조건 {invalidation_count}개가 있고 아직 발동되지 않았다."
                    if invalidation_count
                    else "무효화 조건이 없어 thesis가 틀렸을 때 빠지는 기준이 없다."
                )
            ),
            next_step=(
                "발동된 무효화 조건을 최신 원천 근거와 대조하고 축소/청산 검토를 우선한다."
                if triggered_invalidation_count
                else ("무효화 조건을 최소 1개 이상 작성한다." if not invalidation_count else "무효화 조건이 발동되는지 계속 감시한다.")
            ),
            facts=[
                _professional_fact("무효화 조건", f"{invalidation_count}개"),
                _professional_fact("발동", f"{triggered_invalidation_count}개"),
            ],
        ),
        _thesis_lifecycle_gate(
            gate_key="valuation",
            title="가격이 합리적인가",
            status="pass" if valuation.get("has_view") or target_range_available else "warning",
            decision="좋은 thesis라도 밸류에이션 맥락 없이는 부족하다",
            detail=(
                "밸류에이션 민감도와 목표가 범위가 연결되어 있다."
                if valuation.get("has_view") or target_range_available
                else "밸류에이션 맥락이 없어 좋은 기업을 비싸게 따라사는 위험을 평가하기 어렵다."
            ),
            next_step="DCF-lite, 상대 배수, 시나리오 범위, 안전마진 관점을 보강한다." if not valuation.get("has_view") and not target_range_available else "밸류에이션 가정이 뉴스/실적 변화와 맞는지 본다.",
            facts=[
                _professional_fact("기준 시나리오", valuation.get("base_case") or _valuation_target_range_case_text(target_range) or "미정"),
                _professional_fact("목표가 기준", _format_currency_text(target_range.get("target_base"), target_range.get("currency_code"))),
                _professional_fact("상승여지", _format_signed_percent_text(_number(target_range.get("upside_base")))),
                _professional_fact("안전마진", valuation.get("margin_of_safety_view") or _format_signed_percent_text(_number(target_range.get("margin_of_safety")))),
            ],
        ),
        _thesis_lifecycle_gate(
            gate_key="review_cadence",
            title="언제 다시 보는가",
            status="warning" if not next_review_date or review_overdue else "pass",
            decision="재검토일이 있어야 장기 thesis가 방치되지 않는다",
            detail=(
                "다음 재검토일이 지났다. 최신 뉴스, 가격, 재무, 포지션 정보를 반영해 다시 검토해야 한다."
                if review_overdue
                else (
                    f"다음 재검토일은 {next_review_date}이다."
                    if next_review_date
                    else "다음 재검토일이 없어 thesis가 오래 방치될 수 있다."
                )
            ),
            next_step="thesis review runner를 실행하거나 최신 증거로 수동 검토한다." if not next_review_date or review_overdue else "정해진 재검토일까지 신규 근거를 누적한다.",
            facts=[
                _professional_fact("최근 검토", latest_reviewed_at or "미정"),
                _professional_fact("다음 검토", next_review_date or "미정"),
            ],
        ),
        _thesis_lifecycle_gate(
            gate_key="evidence_freshness",
            title="최근 근거가 검토에 반영됐는가",
            status="blocked" if evidence_count == 0 else ("warning" if new_evidence_after_review or not latest_evidence_at else "pass"),
            decision="최신 근거가 최신 thesis review보다 늦으면 다시 봐야 한다",
            detail=(
                "연결된 원천 근거가 없어 thesis를 검증할 수 없다."
                if evidence_count == 0
                else (
                    "최신 근거가 최근 thesis review 이후에 들어왔다. 이 근거를 반영해 thesis를 다시 검토해야 한다."
                    if new_evidence_after_review
                    else (
                        f"최신 근거 시각은 {latest_evidence_at}이고 현재 review가 이를 덮고 있다."
                        if latest_evidence_at
                        else "근거는 있지만 관측 시각이 없어 freshness 판단은 주의로 남긴다."
                    )
                )
            ),
            next_step=(
                "원천 뉴스/공시/성과 근거를 thesis evidence에 연결한다."
                if evidence_count == 0
                else ("새 근거를 최신 thesis review에 반영한다." if new_evidence_after_review or not latest_evidence_at else "새 근거가 들어오면 review freshness를 다시 계산한다.")
            ),
            facts=[
                _professional_fact("원천 이벤트", f"{source_event_count}개"),
                _professional_fact("성과 근거", f"{performance_evidence_count}개"),
                _professional_fact("최신 근거", latest_evidence_at or "미정"),
            ],
        ),
        _thesis_lifecycle_gate(
            gate_key="order_boundary",
            title="주문 경계",
            status="pass",
            decision="thesis 검토는 주문을 만들지 않는다",
            detail="이 gate는 보유 논리 품질 점검이며 실거래 주문, 가상 주문, 목표 비중을 생성하지 않는다.",
            next_step="실거래는 별도 broker boundary, 계좌 권한, kill switch 승인 전까지 계속 닫아둔다.",
            facts=[
                _professional_fact("자동 주문", "없음"),
                _professional_fact("주문 전송", "차단"),
            ],
        ),
    ]
    blocked_count = sum(1 for gate in gates if gate["status"] == "blocked")
    warning_count = sum(1 for gate in gates if gate["status"] == "warning")
    if blocked_count:
        status = "blocked"
        summary = "필수 thesis gate가 막혀 있다. 보유/추천 판단 전에 무효화 조건, 원천 근거, 핵심 주장을 먼저 보강해야 한다."
    elif warning_count:
        status = "review_required"
        summary = "핵심 thesis는 존재하지만 보강 또는 재검토가 필요한 gate가 남아 있다. 장기 보유 판단 전에 표시된 주의 항목을 확인한다."
    else:
        status = "complete"
        summary = "핵심 주장, 촉매, 리스크, 무효화 조건, 밸류에이션, 재검토 주기, 근거 freshness가 모두 연결되어 있다."

    return {
        "status": status,
        "summary": summary,
        "gate_count": len(gates),
        "pass_count": sum(1 for gate in gates if gate["status"] == "pass"),
        "warning_count": warning_count,
        "blocked_count": blocked_count,
        "latest_evidence_at": latest_evidence_at,
        "latest_reviewed_at": latest_reviewed_at,
        "next_review_date": next_review_date,
        "automatic_order_allowed": False,
        "broker_submit_allowed": False,
        "order_boundary": "read_only_no_order",
        "gates": gates,
    }


def _thesis_lifecycle_gate(
    *,
    gate_key: str,
    title: str,
    status: str,
    decision: str,
    detail: str,
    next_step: str,
    facts: list[dict[str, str]],
) -> dict[str, Any]:
    return {
        "gate_key": gate_key,
        "title": title,
        "status": status,
        "decision": decision,
        "detail": detail,
        "next_step": next_step,
        "facts": facts,
        "automatic_order_allowed": False,
        "broker_submit_allowed": False,
        "order_boundary": "read_only_no_order",
    }


def _parse_frontend_datetime(value: Any) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        if len(text) == 10:
            return datetime.combine(date.fromisoformat(text), datetime.min.time(), tzinfo=timezone.utc)
        return datetime.fromisoformat(text.replace("Z", "+00:00")).astimezone(timezone.utc)
    except ValueError:
        return None


def _format_frontend_datetime(value: datetime | None) -> str | None:
    if value is None:
        return None
    return value.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def build_live_ai_evidence_detail_response(
    parsed: ParsedApiPath,
    *,
    config: RuntimeConfig,
    executor: PsqlCommandExecutor | None,
    generated_at: str,
) -> dict[str, Any]:
    identifier = _parse_detail_identifier(parsed.path, "/api/ai-evidence/")
    state = load_frontend_ai_evidence_detail_state(config=config, executor=executor, identifier=identifier)
    instrument = _as_dict(state.get("instrument"))
    classification = _as_dict(state.get("classification"))
    extraction_run = _as_dict(state.get("extraction_run"))
    cluster_summary = _as_dict(state.get("cluster_summary"))
    news_candidate = _as_dict(state.get("news_candidate"))
    data = {
        "evidence_id": _ai_evidence_detail_id(state, identifier),
        "title": str(state.get("title") or ""),
        "evidence_type": str(state.get("evidence_type") or "source_document_event"),
        "event_at": _timestamp(state.get("event_at")),
        "instrument": {
            "symbol": str(instrument.get("symbol") or "UNKNOWN").upper(),
            "instrument_id": _opaque_id("instrument", instrument.get("instrument_id"), "unknown"),
        },
        "source_document_id": _source_document_detail_id_from_raw(state.get("source_document_id")),
        "korean_title": _optional_text(state.get("korean_title")),
        "korean_summary": _optional_text(state.get("korean_summary")),
        "translation_confidence": _number(state.get("translation_confidence")),
        "classification": {
            "theme_key": str(classification.get("theme_key") or "UNCLASSIFIED"),
            "theme_name": str(classification.get("theme_name") or "Unclassified"),
            "impact_direction": str(classification.get("impact_direction") or "unknown"),
            "impact_score": _number(classification.get("impact_score")),
        },
        "extraction_run": {
            "run_id": _opaque_id("pipeline-run", extraction_run.get("run_id"), "unknown"),
            "status": str(extraction_run.get("status") or "unknown"),
            "provider": str(extraction_run.get("provider") or "unknown"),
            "model_id": str(extraction_run.get("model_id") or "unknown"),
            "prompt_version": str(extraction_run.get("prompt_version") or "unknown"),
            "finished_at": _timestamp(extraction_run.get("finished_at")),
            "input_tokens": int(extraction_run.get("input_tokens") or 0),
            "output_tokens": int(extraction_run.get("output_tokens") or 0),
            "estimated_cost_usd": _number(extraction_run.get("estimated_cost_usd")),
            "quality_gate": str(extraction_run.get("quality_gate") or "ai_review_required"),
        },
        "extracted_fields": [_build_extracted_field_payload(item) for item in _as_list(state.get("extracted_fields"))],
        "news_candidate": _build_ai_evidence_news_candidate_payload(news_candidate),
        "retrieval_context_summary": _build_ai_evidence_retrieval_context_payload(
            _as_dict(state.get("retrieval_context_summary"))
        ),
        "source_chunks": [_build_source_chunk_payload(item) for item in _as_list(state.get("source_chunks"))],
        "cluster_summary": _build_ai_evidence_cluster_summary_payload(cluster_summary),
        "cluster_events": [
            _build_ai_evidence_cluster_event_payload(item) for item in _as_list(state.get("cluster_events"))
        ],
        "audit_notes": [
            "AI output is stored as evidence metadata only; it does not place trades or mutate thesis state.",
            "quality_gate requires AI validator review before this event can justify a thesis change.",
        ],
    }
    data["visibility_trace"] = _build_ai_evidence_visibility_trace_payload(data)

    return {
        "contract_version": CONTRACT_VERSION,
        "generated_at": generated_at,
        "data": data,
        "links": _ai_evidence_links(state, identifier=identifier),
    }


def _build_ai_evidence_visibility_trace_payload(data: dict[str, Any]) -> dict[str, Any]:
    candidate = _as_dict(data.get("news_candidate"))
    cluster = _as_dict(data.get("cluster_summary"))
    cluster_events = _as_list(data.get("cluster_events"))
    source_chunks = _as_list(data.get("source_chunks"))
    extracted_fields = _as_list(data.get("extracted_fields"))
    extraction_run = _as_dict(data.get("extraction_run"))
    instrument = _as_dict(data.get("instrument"))
    classification = _as_dict(data.get("classification"))
    source_document_id = str(data.get("source_document_id") or "")
    has_source = bool(source_document_id or any(event.get("source_document_id") for event in cluster_events))
    translated_event_count = sum(
        1 for event in cluster_events if event.get("korean_title") or event.get("korean_summary")
    )
    has_translation = bool(data.get("korean_title") or data.get("korean_summary") or translated_event_count)
    theme_impacts = _as_list(candidate.get("theme_impacts"))
    instrument_impacts = _as_list(candidate.get("instrument_impacts"))
    evidence_type = str(data.get("evidence_type") or "")
    quality_gate = str(extraction_run.get("quality_gate") or "ai_review_required")
    validator_blocked = evidence_type == "news_event_candidate_rejected" or quality_gate == "validator_blocked"
    validator_status = "blocked" if validator_blocked else ("passed" if quality_gate == "ai_review_passed" else "needs_review")
    target_symbol = _visibility_target_symbol(instrument=instrument, candidate_impacts=instrument_impacts, cluster=cluster)
    recommendation_link_status = "needs_neighborhood_lookup" if target_symbol else "macro_or_theme_only"

    return {
        "summary_ko": _visibility_summary_ko(
            evidence_type=evidence_type,
            validator_status=validator_status,
            target_symbol=target_symbol,
            theme_key=str(classification.get("theme_key") or "UNCLASSIFIED"),
        ),
        "source": {
            "status": "available" if has_source else "missing",
            "source_document_id": source_document_id,
            "source_document_count": len({str(event.get("source_document_id") or "") for event in cluster_events if event.get("source_document_id")})
            or (1 if source_document_id else 0),
            "source_chunk_count": len(source_chunks),
            "message_ko": "원천 문서와 모델 입력 근거를 대조할 수 있다." if has_source else "원천 문서 링크가 부족하다.",
        },
        "translation": {
            "status": "available" if has_translation else "missing",
            "translated_event_count": translated_event_count or (1 if has_translation else 0),
            "translation_confidence": _number(data.get("translation_confidence")),
            "message_ko": "한국어 제목/요약으로 먼저 검토할 수 있다." if has_translation else "한국어 번역이 없어 원문 대조가 필요하다.",
        },
        "ai_structure": {
            "status": "available" if extracted_fields or theme_impacts or instrument_impacts or cluster else "limited",
            "provider": str(extraction_run.get("provider") or "unknown"),
            "model_id": str(extraction_run.get("model_id") or "unknown"),
            "evidence_type": evidence_type,
            "extracted_field_count": len(extracted_fields),
            "theme_impact_count": len(theme_impacts),
            "instrument_impact_count": len(instrument_impacts),
            "cluster_event_count": int(cluster.get("event_count") or len(cluster_events) or 0),
            "message_ko": _ai_structure_message_ko(evidence_type, len(theme_impacts), len(instrument_impacts), cluster),
        },
        "validator": {
            "status": validator_status,
            "quality_gate": quality_gate,
            "blocked": validator_blocked,
            "decision_ko": _validator_decision_ko(validator_status, extraction_run),
            "reasons_ko": _validator_reasons_ko(
                validator_status=validator_status,
                evidence_type=evidence_type,
                quality_gate=quality_gate,
                source_chunk_count=len(source_chunks),
            ),
        },
        "recommendation_linkage": {
            "status": recommendation_link_status,
            "target_symbol": target_symbol,
            "theme_key": str(classification.get("theme_key") or "UNCLASSIFIED"),
            "message_ko": (
                f"{target_symbol} 종목 맥락과 추천 검토서 연결 여부를 이어서 확인한다."
                if target_symbol
                else "직접 종목이 없는 시장/테마 흐름이면 추천 연결은 전파/사이클 단계에서 판단한다."
            ),
        },
        "steps": [
            {"step_key": "source", "label_ko": "원천 뉴스", "status": "available" if has_source else "missing"},
            {"step_key": "translation", "label_ko": "한국어 번역", "status": "available" if has_translation else "missing"},
            {
                "step_key": "ai_structure",
                "label_ko": "AI 구조화",
                "status": "available" if extracted_fields or theme_impacts or instrument_impacts or cluster else "limited",
            },
            {"step_key": "validator", "label_ko": "validator 판정", "status": validator_status},
            {"step_key": "recommendation_linkage", "label_ko": "추천 연결", "status": recommendation_link_status},
        ],
        "read_only_boundary": {
            "live_llm_call_enabled": False,
            "write_enabled": False,
            "broker_submit_allowed": False,
            "order_boundary": "read_only_no_order",
        },
    }


def _visibility_target_symbol(
    *,
    instrument: Mapping[str, Any],
    candidate_impacts: list[Any],
    cluster: Mapping[str, Any],
) -> str:
    for impact in candidate_impacts:
        impact_dict = _as_dict(impact)
        symbol = str(impact_dict.get("target") or impact_dict.get("symbol") or "").upper()
        if symbol and symbol not in {"UNKNOWN", "UNCLASSIFIED"}:
            return symbol
    for symbol_value in _as_list_or_scalars(cluster.get("symbols")):
        symbol = str(symbol_value or "").upper()
        if symbol and symbol not in {"UNKNOWN", "UNCLASSIFIED"}:
            return symbol
    symbol = str(instrument.get("symbol") or "").upper()
    return "" if symbol in {"UNKNOWN", "UNCLASSIFIED"} else symbol


def _visibility_summary_ko(
    *,
    evidence_type: str,
    validator_status: str,
    target_symbol: str,
    theme_key: str,
) -> str:
    target_text = target_symbol or theme_key or "시장/테마"
    if validator_status == "blocked":
        return f"{target_text} 관련 AI 후보지만 validator가 추천 입력 반영을 차단했다."
    if evidence_type == "news_cluster_summary":
        return f"{target_text} 관련 뉴스 묶음이다. 같은 흐름인지와 추천 연결이 과하지 않은지 확인한다."
    return f"{target_text} 관련 AI 근거다. 원천, 번역, 구조화 결과, validator 판정을 순서대로 확인한다."


def _ai_structure_message_ko(
    evidence_type: str,
    theme_impact_count: int,
    instrument_impact_count: int,
    cluster: Mapping[str, Any],
) -> str:
    if evidence_type == "news_cluster_summary":
        return f"뉴스 {int(cluster.get('event_count') or 0)}개를 같은 흐름 후보로 묶었다."
    if theme_impact_count or instrument_impact_count:
        return f"테마 영향 {theme_impact_count}개와 직접 종목 영향 {instrument_impact_count}개를 분리했다."
    return "구조화 필드가 제한적이므로 원천과 추출 필드를 직접 확인해야 한다."


def _validator_decision_ko(status: str, extraction_run: Mapping[str, Any]) -> str:
    if status == "blocked":
        return "추천·보유검토 입력으로 쓰지 않는다."
    if status == "passed":
        return "추천·보유검토의 입력 후보로 사용할 수 있다."
    return f"{extraction_run.get('quality_gate') or 'quality gate'} 상태라 추가 점검이 필요하다."


def _validator_reasons_ko(
    *,
    validator_status: str,
    evidence_type: str,
    quality_gate: str,
    source_chunk_count: int,
) -> list[str]:
    if validator_status == "blocked":
        reasons = [f"품질 조건 `{quality_gate}`로 canonical 영향 반영이 차단됐다."]
        if evidence_type == "news_event_candidate_rejected":
            reasons.append("저장된 후보는 감사와 분류 보강용으로만 남긴다.")
        return reasons
    reasons = [f"품질 조건 `{quality_gate}`가 통과 또는 입력 후보 상태다."]
    if source_chunk_count == 0:
        reasons.append("모델 입력 근거 청크가 없으므로 원천 문서 대조가 필요하다.")
    else:
        reasons.append(f"모델 입력 근거 청크 {source_chunk_count}개가 연결되어 있다.")
    return reasons


