def _build_trading_risk_budget_guardrail_payload(guardrail: dict[str, Any]) -> dict[str, Any]:
    blocking_reasons = guardrail.get("blocking_reasons")
    warning_reasons = guardrail.get("warning_reasons")
    benchmark_drift = _as_dict(guardrail.get("benchmark_drift"))
    return {
        "status": str(guardrail.get("status") or "missing"),
        "eval_run_id": _opaque_id("eval-run", guardrail.get("eval_run_id"), None),
        "as_of_date": str(guardrail.get("as_of_date") or ""),
        "effective_snapshot_date": str(guardrail.get("effective_snapshot_date") or ""),
        "risk_gate_decision": str(guardrail.get("risk_gate_decision") or "missing_portfolio_risk_budget_guardrail"),
        "paper_validation_input_allowed": guardrail.get("paper_validation_input_allowed") is True,
        "blocking_reasons": [
            _reason_code(item)
            for item in blocking_reasons
        ] if isinstance(blocking_reasons, list) else [],
        "warning_reasons": [
            _reason_code(item)
            for item in warning_reasons
        ] if isinstance(warning_reasons, list) else [],
        "benchmark_drift": benchmark_drift,
        "rebalance_candidate_review": _build_benchmark_rebalance_candidate_review_payload(guardrail),
    }


def _build_benchmark_rebalance_candidate_review_payload(
    guardrail: dict[str, Any],
    *,
    position_context_by_symbol: Mapping[str, dict[str, Any]] | None = None,
) -> dict[str, Any]:
    drift = _as_dict(guardrail.get("benchmark_drift"))
    drift_calculated = drift.get("drift_calculated") is True
    coverage_weight = _safe_number(drift.get("composition_coverage_weight")) or 0.0
    active_share = _safe_number(drift.get("active_share"))
    source_type = str(drift.get("source_type") or "")
    source_name = str(drift.get("benchmark_source") or "")
    source_as_of_date = str(drift.get("source_as_of_date") or "")
    benchmark_code = str(drift.get("benchmark_code") or "")
    context_by_symbol = {
        str(symbol).upper(): _as_dict(context)
        for symbol, context in (position_context_by_symbol or {}).items()
    }
    rows = [_build_benchmark_active_position_payload(item) for item in _as_list(drift.get("top_active_positions"))]
    candidates = [
        _benchmark_rebalance_candidate_payload(
            row,
            benchmark_code=benchmark_code,
            benchmark_source=source_name,
            source_type=source_type,
            source_as_of_date=source_as_of_date,
            context=_as_dict(context_by_symbol.get(row["symbol"].upper())),
        )
        for row in rows
        if abs(row["active_weight"]) >= 0.03
    ]
    candidates.sort(key=lambda item: ({"high": 0, "medium": 1, "watch": 2}[item["severity"]], -abs(item["active_weight"]), item["symbol"]))
    candidates = [{**item, "priority": index + 1} for index, item in enumerate(candidates[:8])]
    decision_counts = _normalize_count_map(
        _count_by(candidates, "review_decision"),
        keys=("reduce_watch", "needs_thesis_update", "hold_with_thesis", "review_required"),
    )

    if guardrail.get("status") != "loaded":
        status = "missing_guardrail"
    elif not drift_calculated:
        status = "missing_benchmark_drift"
    elif coverage_weight < 0.95:
        status = "partial_benchmark_composition"
    elif candidates:
        status = "review_required"
    else:
        status = "within_review_band"

    return {
        "status": status,
        "candidate_count": len(candidates),
        "decision_counts": decision_counts,
        "benchmark_code": benchmark_code,
        "benchmark_source": source_name,
        "source_type": source_type,
        "source_as_of_date": source_as_of_date,
        "active_share": active_share,
        "composition_coverage_weight": coverage_weight,
        "review_threshold_active_weight": 0.03,
        "automatic_order_allowed": False,
        "broker_submit_allowed": False,
        "order_boundary": "read_only_no_order",
        "candidates": candidates,
        "next_actions": _benchmark_rebalance_candidate_next_actions(status),
    }


def _benchmark_rebalance_candidate_payload(
    row: dict[str, Any],
    *,
    benchmark_code: str,
    benchmark_source: str,
    source_type: str,
    source_as_of_date: str,
    context: dict[str, Any],
) -> dict[str, Any]:
    active_weight = row["active_weight"]
    direction = "overweight" if active_weight > 0 else "underweight"
    abs_active = abs(active_weight)
    if abs_active >= 0.20:
        severity = "high"
    elif abs_active >= 0.10:
        severity = "medium"
    else:
        severity = "watch"
    suggested_action = (
        "trim_active_overweight_review"
        if direction == "overweight"
        else "review_active_underweight_gap"
    )
    review_decision = _benchmark_rebalance_review_decision(
        direction=direction,
        abs_active=abs_active,
        context=context,
    )
    decision_label = _benchmark_rebalance_decision_label(review_decision)
    next_review_action = _benchmark_rebalance_next_review_action(review_decision)
    related_links = _benchmark_rebalance_related_links(row["symbol"], context)
    rationale = (
        f"{row['symbol']}는 포트폴리오 {row['portfolio_weight']:.1%}, 벤치마크 {row['benchmark_weight']:.1%}, "
        f"벤치마크 대비 괴리 +{active_weight:.1%}이다. 투자 논리, 세금/비용, 섹터 집중도를 확인한 뒤 축소 여부만 검토한다."
        if direction == "overweight"
        else f"{row['symbol']}는 포트폴리오 {row['portfolio_weight']:.1%}, 벤치마크 {row['benchmark_weight']:.1%}, "
        f"벤치마크 대비 괴리 {active_weight:.1%}이다. 의도적 미보유인지 데이터/투자 논리 공백인지 검토한다."
    )
    return {
        "symbol": row["symbol"],
        "current_weight": row["portfolio_weight"],
        "benchmark_weight": row["benchmark_weight"],
        "active_weight": active_weight,
        "direction": direction,
        "severity": severity,
        "suggested_review_action": suggested_action,
        "review_decision": review_decision,
        "decision_label": decision_label,
        "next_review_action": next_review_action,
        "professional_review_required": True,
        "source_evidence": {
            "benchmark_code": benchmark_code,
            "benchmark_source": benchmark_source,
            "source_type": source_type,
            "source_as_of_date": source_as_of_date,
            "current_weight": row["portfolio_weight"],
            "benchmark_weight": row["benchmark_weight"],
            "active_weight": active_weight,
            "active_weight_abs": abs_active,
            "review_threshold_active_weight": 0.03,
        },
        "related_thesis_id": related_links["related_thesis_id"],
        "related_recommendation_id": related_links["related_recommendation_id"],
        "related_recommendation_action": related_links["related_recommendation_action"],
        "related_recommended_weight": related_links["related_recommended_weight"],
        "links": related_links["links"],
        "decision_path": [
            {
                "step": "benchmark_source",
                "label": "벤치마크 원천",
                "detail": benchmark_source or source_type or "source 없음",
            },
            {
                "step": "drift_measurement",
                "label": "비중 차이",
                "detail": f"포트폴리오 {row['portfolio_weight']:.1%} / 벤치마크 {row['benchmark_weight']:.1%} / 괴리 {active_weight:+.1%}",
            },
            {
                "step": "review_decision",
                "label": decision_label,
                "detail": next_review_action,
            },
            {
                "step": "order_boundary",
                "label": "주문 금지",
                "detail": "이 결정은 검토 후보이며 자동 주문이나 broker 전송을 허용하지 않는다.",
            },
        ],
        "rationale": rationale,
        "automatic_order_allowed": False,
        "broker_submit_allowed": False,
        "order_boundary": "read_only_no_order",
    }


def _benchmark_rebalance_review_decision(*, direction: str, abs_active: float, context: dict[str, Any]) -> str:
    if direction == "overweight" and abs_active >= 0.10:
        return "reduce_watch"
    if direction == "underweight":
        return "needs_thesis_update"
    if context.get("active_thesis_id") or context.get("linked_thesis_id"):
        return "hold_with_thesis"
    return "review_required"


def _benchmark_rebalance_decision_label(decision: str) -> str:
    return {
        "reduce_watch": "비중 축소 검토",
        "needs_thesis_update": "미보유 사유 확인",
        "hold_with_thesis": "투자 논리 유지 검토",
        "review_required": "포트폴리오 판단 필요",
    }.get(decision, "포트폴리오 판단 필요")


def _benchmark_rebalance_next_review_action(decision: str) -> str:
    if decision == "reduce_watch":
        return "추가 매수는 막고 thesis, 밸류에이션, 세금/비용, 섹터 집중도를 확인한 뒤 축소 여부만 검토한다."
    if decision == "needs_thesis_update":
        return "의도적으로 보유하지 않는 종목인지, 놓친 핵심 노출인지 thesis와 투자 universe 판단을 갱신한다."
    if decision == "hold_with_thesis":
        return "현재 thesis가 벤치마크 괴리를 정당화하는지 확인하고 유지·축소 조건을 갱신한다."
    return "투자 논리, 추천 상태, 보유 비중 정책을 함께 보고 유지·축소·미보유 사유를 결정한다."


def _benchmark_rebalance_related_links(symbol: str, context: dict[str, Any]) -> dict[str, Any]:
    active_thesis_id = _optional_text(context.get("active_thesis_id"))
    if active_thesis_id is None and context.get("linked_thesis_id") is not None:
        active_thesis_id = _opaque_id("thesis", context.get("linked_thesis_id"), None)
    recommendation_id = _optional_text(context.get("recommendation_id"))
    if recommendation_id is not None and not recommendation_id.startswith("recommendation-"):
        recommendation_id = _opaque_id("recommendation", recommendation_id, None)
    links: dict[str, str] = {"stock": f"/stocks/{quote(symbol, safe='')}"}
    if active_thesis_id:
        links["thesis"] = f"/theses/{quote(active_thesis_id, safe='')}"
    if recommendation_id:
        links["recommendation"] = f"/recommendations/{quote(recommendation_id, safe='')}"
    return {
        "related_thesis_id": active_thesis_id,
        "related_recommendation_id": recommendation_id,
        "related_recommendation_action": _optional_text(context.get("recommendation_action")),
        "related_recommended_weight": _safe_number(context.get("recommended_weight")),
        "links": links,
    }


def _benchmark_rebalance_candidate_next_actions(status: str) -> list[str]:
    if status == "review_required":
        return [
            "벤치마크 대비 괴리가 큰 후보부터 투자 논리, 섹터/테마 집중도, 세금/비용을 검토한다.",
            "검토 후보는 주문 지시가 아니며 주문 전송은 계속 금지한다.",
        ]
    if status == "within_review_band":
        return ["벤치마크 대비 큰 괴리 후보는 없다. 정기 포트폴리오 검토만 유지한다."]
    if status == "partial_benchmark_composition":
        return ["부분 benchmark 구성비이므로 리밸런싱 후보로 쓰지 말고 full holdings source를 먼저 보강한다."]
    if status == "missing_benchmark_drift":
        return ["benchmark drift를 먼저 계산한 뒤 후보를 만든다."]
    return ["최신 portfolio risk budget guardrail을 먼저 실행한다."]


def _build_benchmark_drift_quality_payload(guardrail: dict[str, Any]) -> dict[str, Any]:
    drift = _as_dict(guardrail.get("benchmark_drift"))
    drift_status = str(drift.get("status") or "missing")
    drift_calculated = drift.get("drift_calculated") is True
    coverage_weight = _safe_number(drift.get("composition_coverage_weight")) or 0.0
    active_share = _safe_number(drift.get("active_share"))
    source_as_of_date = str(drift.get("source_as_of_date") or "")
    guardrail_as_of_date = str(guardrail.get("as_of_date") or "")
    source_age_days = _date_age_days(source_as_of_date, guardrail_as_of_date)
    stale = source_age_days is not None and source_age_days > 45
    top_positions = [_build_benchmark_active_position_payload(item) for item in _as_list(drift.get("top_active_positions"))]
    outliers = [item for item in top_positions if abs(item["active_weight"]) >= 0.10]
    rebalance_review = _build_benchmark_rebalance_candidate_review_payload(guardrail)
    outlier_symbols = {item["symbol"] for item in outliers}
    outlier_decisions = [
        item
        for item in _as_list(rebalance_review.get("candidates"))
        if str(item.get("symbol") or "") in outlier_symbols
    ]
    active_share_outlier = active_share is not None and active_share >= 0.30

    if guardrail.get("status") != "loaded":
        status = "missing_guardrail"
    elif not drift_calculated:
        status = "missing_benchmark_composition"
    elif stale:
        status = "stale_composition"
    elif coverage_weight < 0.95:
        status = "partial_composition"
    elif outliers or active_share_outlier:
        status = "drift_outlier_review"
    else:
        status = "ok"

    checks = [
        {
            "check_key": "composition_available",
            "status": "passed" if drift_calculated else "blocked",
            "detail": "벤치마크 구성비로 종목별 괴리를 계산했다." if drift_calculated else "벤치마크 구성비가 없어 drift를 계산하지 않았다.",
        },
        {
            "check_key": "composition_coverage",
            "status": "passed" if coverage_weight >= 0.95 else "warning",
            "detail": f"구성비 합계 {coverage_weight:.1%}. 95% 미만이면 전체 벤치마크 drift로 해석하지 않는다.",
        },
        {
            "check_key": "source_freshness",
            "status": "passed" if source_age_days is not None and source_age_days <= 45 else "warning",
            "detail": (
                f"벤치마크 구성 기준일이 {source_age_days}일 전이다."
                if source_age_days is not None
                else "벤치마크 구성 기준일을 확인할 수 없다."
            ),
        },
        {
            "check_key": "drift_outliers",
            "status": "warning" if outliers or active_share_outlier else "passed",
            "detail": f"개별 벤치마크 괴리 10%p 이상 {len(outliers)}개, 전체 괴리 {active_share:.1%}." if active_share is not None else "전체 괴리가 계산되지 않았다.",
        },
    ]

    return {
        "status": status,
        "guardrail_status": str(guardrail.get("status") or "missing"),
        "guardrail_eval_run_id": _opaque_id("eval-run", guardrail.get("eval_run_id"), None),
        "guardrail_as_of_date": guardrail_as_of_date,
        "drift_status": drift_status,
        "drift_calculated": drift_calculated,
        "benchmark_code": str(drift.get("benchmark_code") or ""),
        "benchmark_source": str(drift.get("benchmark_source") or ""),
        "source_type": str(drift.get("source_type") or ""),
        "source_as_of_date": source_as_of_date,
        "source_age_days": source_age_days,
        "component_count": int(_safe_number(drift.get("component_count")) or 0),
        "composition_coverage_weight": coverage_weight,
        "active_share": active_share,
        "total_absolute_drift": _safe_number(drift.get("total_absolute_drift")),
        "top_active_positions": top_positions,
        "outlier_positions": outliers[:5],
        "outlier_decisions": outlier_decisions[:5],
        "review_candidate_count": int(rebalance_review.get("candidate_count") or 0),
        "review_decision_counts": _as_dict(rebalance_review.get("decision_counts")),
        "automatic_order_allowed": False,
        "broker_submit_allowed": False,
        "order_boundary": "read_only_no_order",
        "checks": checks,
        "next_actions": _benchmark_drift_quality_next_actions(status),
    }


def _build_portfolio_review_decision_history_payload(payload: dict[str, Any]) -> dict[str, Any]:
    status = str(payload.get("status") or "missing")
    decision_status = str(payload.get("decision_status") or ("missing" if status == "missing" else "unknown"))
    guardrails = _as_dict(payload.get("guardrails"))
    decisions = [_build_portfolio_review_history_decision_payload(item) for item in _as_list(payload.get("latest_decisions"))]
    top_decision = _build_portfolio_review_history_decision_payload(_as_dict(payload.get("top_decision")))
    if not top_decision["symbol"] and decisions:
        top_decision = decisions[0]
    if not top_decision["symbol"]:
        top_decision = None
    return {
        "status": status,
        "eval_run_id": _opaque_id("eval-run", payload.get("eval_run_id"), None),
        "created_at": _timestamp(payload.get("created_at")),
        "eval_name": str(payload.get("eval_name") or "portfolio_review_decision_history"),
        "dataset_version": str(payload.get("dataset_version") or "portfolio-review-decision-history-v1"),
        "as_of_date": str(payload.get("as_of_date") or ""),
        "portfolio_name": str(payload.get("portfolio_name") or DEFAULT_PORTFOLIO_NAME),
        "source_portfolio_coverage_as_of_date": str(payload.get("source_portfolio_coverage_as_of_date") or ""),
        "coverage_measurement_end_date": str(payload.get("coverage_measurement_end_date") or ""),
        "decision_status": decision_status,
        "decision_count": int(_safe_number(payload.get("decision_count")) or 0),
        "review_required_count": int(_safe_number(payload.get("review_required_count")) or 0),
        "benchmark_decision_count": int(_safe_number(payload.get("benchmark_decision_count")) or 0),
        "position_sizing_decision_count": int(_safe_number(payload.get("position_sizing_decision_count")) or 0),
        "decision_counts": _as_dict(payload.get("decision_counts")),
        "top_decision": top_decision,
        "latest_decisions": decisions,
        "guardrails": {
            "recommendation_scoring_mutated": guardrails.get("recommendation_scoring_mutated") is True,
            "benchmark_definition_mutated": guardrails.get("benchmark_definition_mutated") is True,
            "portfolio_position_mutated": guardrails.get("portfolio_position_mutated") is True,
            "automatic_rebalance_allowed": guardrails.get("automatic_rebalance_allowed") is True,
            "automatic_order_allowed": guardrails.get("automatic_order_allowed") is True,
            "broker_submit_allowed": guardrails.get("broker_submit_allowed") is True,
            "order_boundary": str(guardrails.get("order_boundary") or "read_only_no_order"),
        },
        "next_action": str(
            payload.get("next_action")
            or "portfolio-review-decision-history-run을 실행해 최신 포트폴리오 검토 결정을 이력화한다."
        ),
    }


