def _professional_source_blocker_label(blocker_code: str, product_type: str) -> str:
    if blocker_code == "fund_company_financial_model_not_applicable" or product_type == "fund_or_etf":
        return "기업 재무 모델 비적용"
    if blocker_code == "sec_companyfacts_missing_us_gaap_facts":
        return "SEC us-gaap facts 없음"
    if blocker_code == "sec_companyfacts_not_found":
        return "SEC companyfacts 미제공"
    if blocker_code == "financial_source_linkage_failed":
        return "재무 원천 연결 실패"
    if blocker_code:
        return blocker_code
    return "누락 source layer"


def _professional_source_default_action(product_type: str) -> str:
    if product_type == "fund_or_etf":
        return "기업 재무 모델 대신 fund/ETF source layer를 기준으로 판단한다."
    return "professional-coverage-expansion-run으로 누락된 전문가식 분석 layer를 보강한다."


def _as_list_or_scalars(value: object) -> list[object]:
    if isinstance(value, list):
        return value
    if value is None:
        return []
    return [value]


def _is_int_like(value: object) -> bool:
    try:
        int(str(value))
    except (TypeError, ValueError):
        return False
    return True


def _benchmark_drift_quality_next_actions(status: str) -> list[str]:
    if status == "ok":
        return ["벤치마크 drift를 보조 위험 지표로 볼 수 있다. 그래도 추천 weight는 자동 변경하지 않는다."]
    if status == "missing_guardrail":
        return ["portfolio-risk-budget-guardrail-run을 먼저 실행해 최신 위험 예산 평가를 만든다."]
    if status == "missing_benchmark_composition":
        return ["benchmark-composition-import-run으로 repo 밖 benchmark holdings CSV를 적재한다."]
    if status == "stale_composition":
        return ["benchmark holdings 파일을 최신 기준일로 다시 가져온 뒤 import를 재실행한다."]
    if status == "partial_composition":
        return ["부분 구성비이므로 전체 괴리로 해석하지 말고 전체 holdings source를 보강한다."]
    if status == "drift_outlier_review":
        return ["전체 괴리와 큰 종목별 괴리를 포트폴리오 위험 예산 검토에서 먼저 확인한다."]
    return ["benchmark drift 품질 상태를 확인한다."]


